import{_ as a,o,c as t,a5 as c}from"./chunks/framework.CXvGqWf0.js";const m=JSON.parse('{"title":"漫画 · 第 23 话 层叠层：@layer 终结 !important 战争","description":"","frontmatter":{},"headers":[],"relativePath":"comics/css/EP.23-cascade-layers.md","filePath":"comics/css/EP.23-cascade-layers.md","lastUpdated":1793421609000}'),r={name:"comics/css/EP.23-cascade-layers.md"};function d(i,e,s,l,n,p){return o(),t("div",null,[...e[0]||(e[0]=[c('<h1 id="漫画-·-第-23-话-层叠层-layer-终结-important-战争" tabindex="-1">漫画 · 第 23 话 层叠层：@layer 终结 !important 战争 <a class="header-anchor" href="#漫画-·-第-23-话-层叠层-layer-终结-important-战争" aria-label="Permalink to &quot;漫画 · 第 23 话 层叠层：@layer 终结 !important 战争&quot;">​</a></h1><blockquote><p>对应正文：<a href="./../../docs/css/13-cascade-layers">docs/css/13-cascade-layers.md</a> ｜ 原画：<a href="./EP.23-cascade-layers.svg">EP.23-cascade-layers.svg</a></p></blockquote><h2 id="登场角色" tabindex="-1">登场角色 <a class="header-anchor" href="#登场角色" aria-label="Permalink to &quot;登场角色&quot;">​</a></h2><ul><li><strong>像素酱</strong>：CSS 造型师，本话主角。引入 UI 框架后覆盖样式越写越具体，<code>!important</code> 满天飞，DevTools 里找不到谁在生效。</li><li><strong>标签君</strong>：HTML5 结构师，搬出 <code>@layer</code> 五层架构，让&quot;reset &lt; base &lt; components &lt; utilities &lt; 未分层&quot;的优先级关系清晰可预期。</li></ul><h2 id="剧情梗概" tabindex="-1">剧情梗概 <a class="header-anchor" href="#剧情梗概" aria-label="Permalink to &quot;剧情梗概&quot;">​</a></h2><p>选择器章（EP.01）讲了特异性三元组，但特异性只是层叠的第三层。像素酱先被 <code>!important</code> 军备竞赛折磨——框架用 <code>!important</code>，业务用更具体的选择器 + <code>!important</code>，最后 DOM 一改全盘崩。标签君引入 <code>@layer</code>，把样式分层：层顺序比特异性更强，低层 <code>!important</code> 也赢不了高层普通规则。</p><h2 id="分格解读" tabindex="-1">分格解读 <a class="header-anchor" href="#分格解读" aria-label="Permalink to &quot;分格解读&quot;">​</a></h2><h3 id="格1-·-痛点现场" tabindex="-1">格1 · 痛点现场 <a class="header-anchor" href="#格1-·-痛点现场" aria-label="Permalink to &quot;格1 · 痛点现场&quot;">​</a></h3><p>框架 <code>.btn { background: blue !important; }</code>，业务覆盖 <code>.page .btn { background: red !important; }</code>，再覆盖 <code>#app .page .btn { background: green !important; }</code>。特异性从 (0,1,0) 涨到 (1,2,0)，最终只能靠 <code>!important</code> 硬刚。DOM 结构一变，覆盖链断裂。</p><h3 id="格2-·-机制登场" tabindex="-1">格2 · 机制登场 <a class="header-anchor" href="#格2-·-机制登场" aria-label="Permalink to &quot;格2 · 机制登场&quot;">​</a></h3><p><code>@layer reset, base, components, utilities;</code> 声明层序，层块内写规则。层叠决胜顺序变为：来源 → 层 → 特异性 → 出现顺序。关键洞察：<strong>层 &gt; 特异性</strong>——<code>utilities</code> 层的 <code>.class</code> 能覆盖 <code>base</code> 层的 <code>#id !important</code>。未分层规则优先级最高，用于页面特有覆盖。</p><h3 id="格3-·-落地收束" tabindex="-1">格3 · 落地收束 <a class="header-anchor" href="#格3-·-落地收束" aria-label="Permalink to &quot;格3 · 落地收束&quot;">​</a></h3><p>五层架构可视化：reset → base → components → utilities → 未分层。覆盖示例：<code>overrides</code> 层的普通规则覆盖 <code>utilities</code> 层的 <code>!important</code>（因为层序更晚）。<code>!important</code> 逆序规则：分层中 <code>base !important</code> &gt; <code>utilities !important</code>，防止工具层封死下层。嵌套层 <code>@layer framework { @layer reset {} }</code> 和 <code>@import &quot;tw.css&quot; layer(tw)</code> 让第三方框架无缝接入。</p><h2 id="码叔划重点" tabindex="-1">码叔划重点 <a class="header-anchor" href="#码叔划重点" aria-label="Permalink to &quot;码叔划重点&quot;">​</a></h2><ol><li>层声明顺序即优先级：先声明的层 &lt; 后声明的层，未分层规则最高。</li><li>层顺序比特异性更强：低层 <code>#id !important</code> 也赢不了高层 <code>.class</code>。</li><li>分层规则中 <code>!important</code> 按层逆序——滥用 <code>!important</code> 时层叠层也救不了你。</li></ol><h2 id="自测一题" tabindex="-1">自测一题 <a class="header-anchor" href="#自测一题" aria-label="Permalink to &quot;自测一题&quot;">​</a></h2><p><strong>问</strong>：<code>@layer base { .a { color: red !important; } }</code> 和 <code>@layer utilities { .a { color: green; } }</code>，<code>.a</code> 最终是什么颜色？为什么？</p><p><strong>答</strong>：红色。因为 <code>base</code> 层中的 <code>!important</code> 在层逆序中优先级高于 <code>utilities</code> 层的普通规则。层叠层中 <code>!important</code> 的行为与普通层叠相反：先声明的层 <code>!important</code> &gt; 后声明的层 <code>!important</code> &gt; 后声明的层普通规则 &gt; 先声明的层普通规则。</p><h2 id="动手实验" tabindex="-1">动手实验 <a class="header-anchor" href="#动手实验" aria-label="Permalink to &quot;动手实验&quot;">​</a></h2><ul><li>五层架构 + 层覆盖演示 + 嵌套层 + !important 逆序 + 层可视化：<a href="./../../examples/css/13-cascade-layers/index-01-cascade-layers.html">examples/css/13-cascade-layers/</a></li></ul><h2 id="下一话预告" tabindex="-1">下一话预告 <a class="header-anchor" href="#下一话预告" aria-label="Permalink to &quot;下一话预告&quot;">​</a></h2><p>第 24 话《现代颜色》——<code>oklch()</code> 感知均匀、<code>color-mix()</code> 混色、<code>light-dark()</code> 双主题，设计系统的颜色革命。</p>',22)])])}const u=a(r,[["render",d]]);export{m as __pageData,u as default};
